#include <bits/stdc++.h>
using namespace std;

struct Scan {
    deque<string> buffer;

    Scan() : buffer() {}

    template <class T>
    T next() {
        while (true) {
            if (!buffer.empty()) {
                string token = buffer.front();
                buffer.pop_front();
                stringstream ss(token);
                T value;
                ss >> value;
                return value;
            }
            string line;
            if (!getline(cin, line)) {
                exit(1);
            }
            stringstream ss(line);
            string word;
            buffer.clear();
            while (ss >> word) {
                buffer.push_back(word);
            }
        }
    }
};

void _main() {
    Scan scan;
    size_t res = 0;
    size_t n = scan.next<size_t>();
    size_t m = scan.next<size_t>();
    size_t limit = max(n, m);
    for (size_t i = 0; i <= limit; ++i) {
        for (size_t j = 0; j <= limit; ++j) {
            if (i * i + j == n && i + j * j == m) {
                res += 1;
            }
        }
    }
    cout << res << '\n';
}

int main() {
    _main();
    return 0;
}

